import figs from "@/data/paper-figures.json";

/*
 * The paper's figures, drawn as plain SVG from data/paper-figures.json
 * (generated by scripts/export_paper_figures.py from results/) or, for
 * Figures 2 and 3, computed from the formulas in Section 3.
 * Colours are the site's theme tokens, so every figure follows light/dark mode.
 */

const C = {
  ink: "var(--text-primary)",
  quiet: "var(--text-secondary)",
  muted: "var(--text-muted)",
  grid: "var(--border)",
  accent: "var(--series-1)",
};

const W = 720;

function Frame({
  title,
  subtitle,
  source,
  height,
  label,
  children,
}: {
  title: string;
  subtitle: string;
  source: string;
  height: number;
  label: string;
  children: React.ReactNode;
}) {
  return (
    <figure className="paper-figure">
      <p className="paper-figure-title">{title}</p>
      <p className="paper-figure-sub">{subtitle}</p>
      <div className="paper-figure-scroll">
        <svg viewBox={`0 0 ${W} ${height}`} role="img" aria-label={label} fontSize={12} fontFamily="inherit">
          {children}
        </svg>
      </div>
      <p className="paper-figure-source">Source: {source}</p>
    </figure>
  );
}

function fmt(v: number, d = 2) {
  return v.toFixed(d);
}

/* ---------- Figure 1: architecture ---------- */
function Architecture() {
  const box = (x: number, y: number, w: number, h: number, strong = false) => (
    <rect
      x={x}
      y={y}
      width={w}
      height={h}
      rx={10}
      fill={strong ? C.accent : "none"}
      fillOpacity={strong ? 0.12 : 1}
      stroke={strong ? C.accent : C.muted}
      strokeWidth={strong ? 2 : 1.25}
    />
  );
  const line = (d: string) => <path d={d} fill="none" stroke={C.muted} strokeWidth={1.25} markerEnd="url(#arch-arrow)" />;
  return (
    <Frame
      title="Two retrievers run in parallel; only their ranks are fused; a cross-encoder reorders the top 50"
      subtitle="Query-time pipeline with mean latency per query"
      source="results/metrics/*.json (timing), Apple M1 Pro"
      height={250}
      label="Pipeline: query to BM25 and MedCPT in parallel, then RRF fusion, then cross-encoder reranking"
    >
      <defs>
        <marker id="arch-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
          <path d="M0 0L10 5L0 10z" fill={C.muted} />
        </marker>
      </defs>
      {line("M112 125H130V64H150")}
      {line("M112 125H130V186H150")}
      {line("M360 64H378V116H398")}
      {line("M360 186H378V134H398")}
      {line("M548 125H570")}
      {box(16, 101, 96, 48)}
      <text x={64} y={130} textAnchor="middle" fontWeight={600} fill={C.ink}>Query</text>
      {box(150, 28, 210, 72)}
      <text x={166} y={52} fontWeight={600} fill={C.ink}>BM25 (lexical)</text>
      <text x={166} y={70} fontSize={11.5} fill={C.quiet}>Inverted index · k1 = 1.2, b = 0.75</text>
      <text x={166} y={88} fontSize={11.5} fill={C.quiet}>top 100 · 2.2 ms</text>
      {box(150, 150, 210, 72)}
      <text x={166} y={174} fontWeight={600} fill={C.ink}>MedCPT (dense)</text>
      <text x={166} y={192} fontSize={11.5} fill={C.quiet}>768-d vectors · exact FAISS</text>
      <text x={166} y={210} fontSize={11.5} fill={C.quiet}>top 100 · 1.9 ms</text>
      {box(398, 89, 150, 72)}
      <text x={414} y={113} fontWeight={600} fill={C.ink}>RRF fusion</text>
      <text x={414} y={131} fontSize={11.5} fill={C.quiet}>Σ 1 / (60 + rank)</text>
      <text x={414} y={149} fontSize={11.5} fill={C.quiet}>ranks, not scores</text>
      {box(570, 89, 140, 72, true)}
      <text x={584} y={113} fontWeight={600} fill={C.ink}>Cross-encoder</text>
      <text x={584} y={131} fontSize={11.5} fill={C.ink}>reorders top 50</text>
      <text x={584} y={149} fontSize={11.5} fill={C.ink}>1,946 ms</text>
    </Frame>
  );
}

/* ---------- shared line-chart helpers ---------- */
function polyline(points: [number, number][]) {
  return points.map(([x, y], i) => `${i ? "L" : "M"}${x.toFixed(1)} ${y.toFixed(1)}`).join("");
}

function spreadLabels<T extends { y: number }>(items: T[], gap = 15): (T & { ly: number })[] {
  const sorted = [...items].sort((a, b) => a.y - b.y);
  let prev = -Infinity;
  return sorted.map((it) => {
    const ly = Math.max(it.y + 4, prev + gap);
    prev = ly;
    return { ...it, ly };
  });
}

/* ---------- Figure 2a: BM25 saturation ---------- */
function Saturation() {
  const x0 = 56, x1 = 600, y0 = 20, yb = 230;
  const X = (tf: number) => x0 + (tf / 20) * (x1 - x0);
  const Y = (w: number) => yb - (w / 3) * (yb - y0);
  const ks = [0.5, 1.2, 2.0];
  const w = (k: number, tf: number) => (tf * (k + 1)) / (tf + k);
  return (
    <Frame
      title="With k1 = 1.2, the 10th occurrence of a word adds about 2% of the weight of the first"
      subtitle="BM25 term-frequency factor tf·(k1 + 1) / (tf + k1) at average document length; it approaches k1 + 1"
      source="computed from the BM25 formula (Section 3.3)"
      height={280}
      label="BM25 term-frequency saturation curves for k1 = 0.5, 1.2 and 2.0"
    >
      {[0, 1, 2, 3].map((v) => (
        <g key={v}>
          <line x1={x0} x2={x1} y1={Y(v)} y2={Y(v)} stroke={C.grid} />
          <text x={x0 - 8} y={Y(v) + 4} textAnchor="end" fill={C.quiet}>{v}</text>
        </g>
      ))}
      {[0, 5, 10, 15, 20].map((v) => (
        <text key={v} x={X(v)} y={yb + 18} textAnchor="middle" fill={C.quiet}>{v}</text>
      ))}
      <text x={(x0 + x1) / 2} y={yb + 40} textAnchor="middle" fontSize={11.5} fill={C.quiet}>term frequency tf(t, d)</text>
      {ks.map((k) => {
        const main = k === 1.2;
        const pts: [number, number][] = Array.from({ length: 21 }, (_, tf) => [X(tf), Y(w(k, tf))]);
        return (
          <g key={k}>
            <path d={polyline(pts)} fill="none" stroke={main ? C.accent : C.muted} strokeWidth={main ? 2.5 : 1.5} />
            <text x={X(20) + 10} y={Y(w(k, 20)) + 4} fill={main ? C.ink : C.quiet} fontWeight={main ? 600 : 400}>
              k1 = {k}
            </text>
          </g>
        );
      })}
    </Frame>
  );
}

/* ---------- Figure 2b: idf curves ---------- */
function Idf() {
  const N = 3633;
  const x0 = 56, x1 = 600, y0 = 20, yb = 250;
  const X = (df: number) => x0 + (Math.log10(df) / Math.log10(N)) * (x1 - x0);
  const Y = (v: number) => y0 + ((9 - v) / 18) * (yb - y0);
  const dfs = Array.from({ length: 80 }, (_, i) => Math.round(Math.pow(N, i / 79))).filter((d, i, a) => a.indexOf(d) === i);
  const bm25 = (df: number) => Math.log((N - df + 0.5) / (df + 0.5));
  const tfidf = (df: number) => Math.log((1 + N) / (1 + df)) + 1;
  return (
    <Frame
      title="BM25’s idf turns negative for words in more than half the corpus; TF-IDF’s never drops below 1"
      subtitle="idf as a function of document frequency, N = 3,633 documents, log scale"
      source="computed from the idf formulas in Sections 3.2 and 3.3"
      height={300}
      label="idf against document frequency for BM25 and TF-IDF"
    >
      {[-8, -4, 0, 4, 8].map((v) => (
        <g key={v}>
          <line x1={x0} x2={x1} y1={Y(v)} y2={Y(v)} stroke={v === 0 ? C.muted : C.grid} />
          <text x={x0 - 8} y={Y(v) + 4} textAnchor="end" fill={C.quiet}>{v}</text>
        </g>
      ))}
      {[1, 10, 100, 1000, N].map((v) => (
        <text key={v} x={X(v)} y={yb + 18} textAnchor="middle" fill={C.quiet}>{v.toLocaleString("en-US")}</text>
      ))}
      <text x={(x0 + x1) / 2} y={yb + 40} textAnchor="middle" fontSize={11.5} fill={C.quiet}>document frequency df(t)</text>
      <line x1={X(N / 2)} x2={X(N / 2)} y1={y0} y2={yb} stroke={C.muted} strokeDasharray="4 4" />
      <text x={X(N / 2) - 6} y={y0 + 12} textAnchor="end" fontSize={11.5} fill={C.quiet}>df = N / 2</text>
      <path d={polyline(dfs.map((d) => [X(d), Y(tfidf(d))]))} fill="none" stroke={C.muted} strokeWidth={2} />
      <path d={polyline(dfs.map((d) => [X(d), Y(bm25(d))]))} fill="none" stroke={C.accent} strokeWidth={2.5} />
      <text x={X(N) + 10} y={Y(tfidf(N)) + 4} fill={C.quiet}>TF-IDF {fmt(tfidf(N), 1)}</text>
      <text x={X(N) + 10} y={Y(bm25(N)) + 4} fontWeight={600} fill={C.ink}>BM25 {fmt(bm25(N), 1)}</text>
    </Frame>
  );
}

/* ---------- Figure 3: RRF decay ---------- */
function RrfDecay() {
  const x0 = 56, x1 = 540, y0 = 20, yb = 230;
  const X = (r: number) => x0 + (Math.log10(r) / 2) * (x1 - x0);
  const Y = (v: number) => yb - v * (yb - y0);
  const ranks = Array.from({ length: 100 }, (_, i) => i + 1);
  const rel = (k: number, r: number) => (k + 1) / (k + r);
  return (
    <Frame
      title="With k = 60, a document at rank 10 still earns 87% of the credit of rank 1"
      subtitle="RRF contribution 1 / (k + rank), relative to rank 1; rank on a log scale"
      source="computed from the RRF formula (Section 3.5)"
      height={280}
      label="Relative RRF credit by rank for k = 1, 10 and 60"
    >
      {[0, 0.25, 0.5, 0.75, 1].map((v) => (
        <g key={v}>
          <line x1={x0} x2={x1} y1={Y(v)} y2={Y(v)} stroke={C.grid} />
          <text x={x0 - 8} y={Y(v) + 4} textAnchor="end" fill={C.quiet}>{Math.round(v * 100)}%</text>
        </g>
      ))}
      {[1, 2, 5, 10, 20, 50, 100].map((v) => (
        <text key={v} x={X(v)} y={yb + 18} textAnchor="middle" fill={C.quiet}>{v}</text>
      ))}
      <text x={(x0 + x1) / 2} y={yb + 40} textAnchor="middle" fontSize={11.5} fill={C.quiet}>rank in a component list</text>
      <line x1={X(10)} x2={X(10)} y1={y0} y2={yb} stroke={C.muted} strokeDasharray="4 4" />
      <text x={X(10) + 6} y={y0 + 12} fontSize={11.5} fill={C.quiet}>end of first page</text>
      {[1, 10, 60].map((k) => {
        const main = k === 60;
        return (
          <g key={k}>
            <path
              d={polyline(ranks.map((r) => [X(r), Y(rel(k, r))]))}
              fill="none"
              stroke={main ? C.accent : C.muted}
              strokeWidth={main ? 2.5 : 1.5}
              strokeOpacity={main || k === 10 ? 1 : 0.6}
            />
            <text x={X(100) + 10} y={Y(rel(k, 100)) + 4} fill={main ? C.ink : C.quiet} fontWeight={main ? 600 : 400}>
              k = {k} (rank 10: {Math.round(rel(k, 10) * 100)}%)
            </text>
          </g>
        );
      })}
    </Frame>
  );
}

/* ---------- Figure 4: recall by depth ---------- */
function Recall() {
  const x0 = 56, x1 = 500, y0 = 20, yb = 250;
  const X = (k: number) => x0 + Math.log10(k / 10) * (x1 - x0);
  const Y = (v: number) => yb - ((v - 0.1) / 0.3) * (yb - y0);
  const slugs = [...new Set(figs.recall.map((r) => r.slug))];
  const series = slugs.map((s) => figs.recall.filter((r) => r.slug === s));
  const ends = spreadLabels(series.map((pts) => ({ s: pts[0].slug, name: pts[0].system, v: pts[pts.length - 1].value, y: Y(pts[pts.length - 1].value) })));
  const lexical = (s: string) => s === "tfidf" || s === "bm25";
  return (
    <Frame
      title="At depth 100, MedCPT finds 35% of relevant documents; the lexical baselines find 23–24%"
      subtitle="Mean Recall@k over 323 test queries; the reranked list is capped at its 50-document pool"
      source="results/metrics/*.json"
      height={300}
      label="Recall at 10, 20, 50 and 100 for six systems"
    >
      {[0.1, 0.2, 0.3, 0.4].map((v) => (
        <g key={v}>
          <line x1={x0} x2={x1} y1={Y(v)} y2={Y(v)} stroke={C.grid} />
          <text x={x0 - 8} y={Y(v) + 4} textAnchor="end" fill={C.quiet}>{fmt(v, 1)}</text>
        </g>
      ))}
      {[10, 20, 50, 100].map((v) => (
        <text key={v} x={X(v)} y={yb + 18} textAnchor="middle" fill={C.quiet}>k = {v}</text>
      ))}
      {series.map((pts) => {
        const s = pts[0].slug, main = s === "medcpt";
        const color = main ? C.accent : C.muted;
        return (
          <g key={s}>
            <path
              d={polyline(pts.map((p) => [X(p.k), Y(p.value)]))}
              fill="none"
              stroke={color}
              strokeOpacity={main ? 1 : lexical(s) ? 0.55 : 0.95}
              strokeWidth={main ? 2.5 : 1.75}
              strokeDasharray={s === "hybrid_reranked" ? "5 4" : undefined}
            />
            {pts.map((p) => (
              <circle key={p.k} cx={X(p.k)} cy={Y(p.value)} r={main ? 3.5 : 2.5} fill={color} fillOpacity={lexical(s) ? 0.55 : 1}>
                <title>{`${p.system}, Recall@${p.k}: ${fmt(p.value, 3)}`}</title>
              </circle>
            ))}
          </g>
        );
      })}
      {ends.map((e) => (
        <g key={e.s}>
          <line x1={X(100) + 4} x2={X(100) + 14} y1={e.y} y2={e.ly - 4} stroke={C.grid} />
          <text x={X(100) + 18} y={e.ly} fontSize={11.5} fontWeight={e.s === "medcpt" ? 600 : 400} fill={e.s === "medcpt" ? C.ink : C.quiet}>
            {e.name} {fmt(e.v, 3)}
          </text>
        </g>
      ))}
    </Frame>
  );
}

/* ---------- Figure 5: significance forest ---------- */
function Forest() {
  const rows = figs.forest;
  const groups = [...new Set(rows.map((r) => r.comparison))];
  const px = 290, qx = 640, y0 = 40, rh = 18, gg = 16;
  const X = (v: number) => px + ((v + 0.08) / 0.25) * (qx - px);
  const Y = (i: number, g: string) => y0 + i * rh + groups.indexOf(g) * gg;
  const H = y0 + rows.length * rh + groups.length * gg + 6;
  const sig = (p: number) => p < 0.05;
  const pText = (p: number) => (p < 0.0001 ? "< 0.0001" : fmt(p, 3));
  return (
    <Frame
      title="Only the move from BM25 to a dense model gives large, significant gains"
      subtitle="Paired difference (later system minus earlier) with 95% bootstrap CI, n = 323; blue = p < 0.05"
      source="results/tables/statistical_tests.json, 30 paired bootstrap tests, 10,000 resamples. *Reranked list holds 50 documents, so its Recall@100 loss is a pool-size artifact."
      height={H}
      label="Forest plot of 30 paired significance tests"
    >
      {[-0.05, 0, 0.05, 0.1, 0.15].map((v) => (
        <g key={v}>
          <line x1={X(v)} x2={X(v)} y1={y0 - 12} y2={H - 6} stroke={v === 0 ? C.muted : C.grid} strokeWidth={v === 0 ? 1.25 : 1} />
          <text x={X(v)} y={y0 - 18} textAnchor="middle" fill={C.quiet}>{v > 0 ? `+${fmt(v)}` : fmt(v)}</text>
        </g>
      ))}
      <text x={qx + 16} y={y0 - 18} fill={C.quiet}>p</text>
      {rows.map((r, i) => {
        const y = Y(i, r.comparison);
        const first = i === 0 || rows[i - 1].comparison !== r.comparison;
        const color = sig(r.p) ? C.accent : C.muted;
        const metric = r.comparison.startsWith("Reranked") && r.metric === "Recall@100" ? "Recall@100*" : r.metric;
        return (
          <g key={`${r.comparison}-${r.metric}`}>
            {first && <text x={8} y={y + 4} fontWeight={600} fill={C.ink}>{r.comparison}</text>}
            <text x={px - 12} y={y + 4} textAnchor="end" fill={C.quiet}>{metric}</text>
            <line x1={X(r.low)} x2={X(r.high)} y1={y} y2={y} stroke={color} strokeWidth={2} />
            <circle cx={X(r.diff)} cy={y} r={4} fill={color}>
              <title>{`${r.comparison}, ${r.metric}: ${r.diff >= 0 ? "+" : ""}${r.diff} [${r.low}, ${r.high}], p = ${pText(r.p)}`}</title>
            </circle>
            <text x={qx + 16} y={y + 4} fill={sig(r.p) ? C.ink : C.quiet}>{pText(r.p)}</text>
          </g>
        );
      })}
    </Frame>
  );
}

/* ---------- Figure 6: rerank pool ablation ---------- */
function Pool() {
  const rows = figs.pool, base = figs.poolBase;
  const yb = 210, y0 = 40;
  const Xp = (i: number, left: number) => left + 20 + i * 120;
  const Yn = (v: number) => yb - ((v - 0.34) / 0.04) * (yb - y0);
  const Ym = (v: number) => yb - ((v - 0.15) / 0.04) * (yb - y0);
  const best = rows.reduce((a, r) => (r.ndcg10 > a.ndcg10 ? r : a), rows[0]);
  const panel = (left: number, title: string, ticks: number[], Y: (v: number) => number, val: (r: (typeof rows)[number]) => number, baseV: number, accent: boolean) => (
    <g>
      <text x={left} y={20} fontWeight={600} fill={C.ink}>{title}</text>
      {ticks.map((v) => (
        <g key={v}>
          <line x1={left} x2={left + 280} y1={Y(v)} y2={Y(v)} stroke={C.grid} />
          <text x={left - 8} y={Y(v) + 4} textAnchor="end" fill={C.quiet}>{fmt(v)}</text>
        </g>
      ))}
      <line x1={left} x2={left + 280} y1={Y(baseV)} y2={Y(baseV)} stroke={C.muted} strokeDasharray="5 4" />
      <text x={left + 280} y={Y(baseV) + 16} textAnchor="end" fontSize={11.5} fill={C.quiet}>hybrid, no rerank {fmt(baseV, 3)}</text>
      <path d={polyline(rows.map((r, i) => [Xp(i, left), Y(val(r))]))} fill="none" stroke={accent ? C.accent : C.muted} strokeWidth={2.5} />
      {rows.map((r, i) => (
        <g key={r.pool}>
          <circle cx={Xp(i, left)} cy={Y(val(r))} r={accent && r === best ? 5 : 3.5} fill={accent ? C.accent : C.muted} />
          <text x={Xp(i, left)} y={Y(val(r)) - 10} textAnchor="middle" fontWeight={accent && r === best ? 600 : 400} fill={C.ink}>{fmt(val(r), 3)}</text>
          <text x={Xp(i, left)} y={yb + 20} textAnchor="middle" fill={C.ink}>P = {r.pool}</text>
          <text x={Xp(i, left)} y={yb + 36} textAnchor="middle" fontSize={11.5} fill={C.quiet}>{fmt(r.ms / 1000, 1)} s/query</text>
        </g>
      ))}
    </g>
  );
  return (
    <Frame
      title="A pool of 50 gives the best nDCG@10; MAP keeps rising with the pool"
      subtitle="Cross-encoder reranking of the hybrid’s top P candidates; dashed line = hybrid without reranking"
      source="results/metrics/reranker_pool_ablation.json"
      height={260}
      label="nDCG@10 and MAP for rerank pools of 20, 50 and 100"
    >
      {panel(56, "nDCG@10", [0.34, 0.35, 0.36, 0.37, 0.38], Yn, (r) => r.ndcg10, base.ndcg10, true)}
      {panel(410, "MAP", [0.15, 0.16, 0.17, 0.18, 0.19], Ym, (r) => r.map, base.map, false)}
    </Frame>
  );
}

/* ---------- Figure 7: cost vs effectiveness ---------- */
function Cost() {
  const rows = figs.cost;
  const x0 = 56, x1 = 660, y0 = 20, yb = 230;
  const X = (ms: number) => x0 + (Math.log10(ms) / Math.log10(3000)) * (x1 - x0);
  const Y = (v: number) => yb - ((v - 0.28) / 0.11) * (yb - y0);
  const sorted = [...rows].sort((a, b) => a.ms - b.ms);
  const frontier: typeof rows = [];
  for (const r of sorted) if (!frontier.length || r.ndcg10 > frontier[frontier.length - 1].ndcg10) frontier.push(r);
  const onFront = (s: string) => frontier.some((f) => f.slug === s);
  const bge = rows.find((r) => r.slug === "bge")!, rr = rows.find((r) => r.slug === "hybrid_reranked")!;
  const place: Record<string, [number, number, "start" | "end"]> = {
    bm25: [10, 16, "start"],
    tfidf: [10, 4, "start"],
    medcpt: [-10, 4, "end"],
    bge: [-6, -12, "end"],
    hybrid_rrf: [10, 16, "start"],
    hybrid_reranked: [-10, -12, "end"],
  };
  return (
    <Frame
      title={`Reranking adds ${fmt(rr.ndcg10 - bge.ndcg10, 3)} nDCG@10 over BGE at ${Math.round(rr.ms / bge.ms)}× the latency`}
      subtitle="Mean latency per query (log scale, Apple M1 Pro) against nDCG@10; dashed line = Pareto frontier"
      source="results/metrics/*.json; reranked latency includes the hybrid first stage"
      height={270}
      label="Latency against nDCG@10 for six systems"
    >
      {[0.28, 0.3, 0.32, 0.34, 0.36, 0.38].map((v) => (
        <g key={v}>
          <line x1={x0} x2={x1} y1={Y(v)} y2={Y(v)} stroke={C.grid} />
          <text x={x0 - 8} y={Y(v) + 4} textAnchor="end" fill={C.quiet}>{fmt(v)}</text>
        </g>
      ))}
      {[1, 10, 100, 1000].map((v) => (
        <text key={v} x={X(v)} y={yb + 18} textAnchor="middle" fill={C.quiet}>{v.toLocaleString("en-US")} ms</text>
      ))}
      <path d={polyline(frontier.map((r) => [X(r.ms), Y(r.ndcg10)]))} fill="none" stroke={C.accent} strokeWidth={1.5} strokeDasharray="5 4" />
      {rows.map((r) => {
        const [dx, dy, anchor] = place[r.slug];
        const f = onFront(r.slug);
        return (
          <g key={r.slug}>
            <circle cx={X(r.ms)} cy={Y(r.ndcg10)} r={f ? 5.5 : 4.5} fill={f ? C.accent : C.muted}>
              <title>{`${r.system}: nDCG@10 ${r.ndcg10}, ${r.ms} ms per query`}</title>
            </circle>
            <text x={X(r.ms) + dx} y={Y(r.ndcg10) + dy} textAnchor={anchor} fontSize={11.5} fontWeight={f ? 600 : 400} fill={f ? C.ink : C.quiet}>
              {r.system}
            </text>
          </g>
        );
      })}
    </Frame>
  );
}

/* ---------- Figure 8: score scales ---------- */
function Scores() {
  const rows = figs.topScores;
  const x0 = 100, x1 = 690;
  const X = (v: number) => x0 + ((v + 10) / 90) * (x1 - x0);
  const jit = (i: number) => ((i * 37) % 23) / 23;
  const yB = 60, yM = 160, band = 56;
  const median = (vs: number[]) => {
    const s = [...vs].sort((a, b) => a - b), h = Math.floor(s.length / 2);
    return s.length % 2 ? s[h] : (s[h - 1] + s[h]) / 2;
  };
  const b = rows.map((r) => r.bm25), m = rows.map((r) => r.medcpt);
  const mb = median(b), mm = median(m);
  return (
    <Frame
      title={`On one scale, BM25 top scores span ${Math.round(Math.min(...b))} to ${Math.round(Math.max(...b))}; MedCPT’s sit between ${Math.round(Math.min(...m))} and ${Math.round(Math.max(...m))}`}
      subtitle={`Score of the rank-1 document for each of the ${rows.length} test queries where BM25 returns results; bar = median`}
      source="results/runs/bm25.json and medcpt.json"
      height={240}
      label="Strip plot of rank-1 scores for BM25 and MedCPT"
    >
      {[-10, 0, 10, 20, 30, 40, 50, 60, 70, 80].map((v) => (
        <g key={v}>
          <line x1={X(v)} x2={X(v)} y1={yB - band / 2 - 8} y2={yM + band / 2 + 8} stroke={v === 0 ? C.muted : C.grid} />
          <text x={X(v)} y={yM + band / 2 + 26} textAnchor="middle" fill={C.quiet}>{v}</text>
        </g>
      ))}
      <text x={8} y={yB + 4} fontWeight={600} fill={C.ink}>BM25</text>
      <text x={8} y={yM + 4} fontWeight={600} fill={C.ink}>MedCPT</text>
      {rows.map((r, i) => (
        <circle key={`b-${r.query}`} cx={X(r.bm25)} cy={yB - band / 2 + jit(i) * band} r={2.5} fill={C.muted} fillOpacity={0.75}>
          <title>{`${r.query}: BM25 top score ${r.bm25}`}</title>
        </circle>
      ))}
      {rows.map((r, i) => (
        <circle key={`m-${r.query}`} cx={X(r.medcpt)} cy={yM - band / 2 + jit(i + 7) * band} r={2.5} fill={C.accent} fillOpacity={0.6}>
          <title>{`${r.query}: MedCPT top score ${r.medcpt}`}</title>
        </circle>
      ))}
      <line x1={X(mb)} x2={X(mb)} y1={yB - band / 2 - 4} y2={yB + band / 2 + 4} stroke={C.ink} strokeWidth={2} />
      <text x={X(mb) + 6} y={yB - band / 2 - 8} fontSize={11.5} fill={C.ink}>median {fmt(mb, 1)}</text>
      <line x1={X(mm)} x2={X(mm)} y1={yM - band / 2 - 4} y2={yM + band / 2 + 4} stroke={C.ink} strokeWidth={2} />
      <text x={X(mm) - 6} y={yM - band / 2 - 8} textAnchor="end" fontSize={11.5} fill={C.ink}>median {fmt(mm, 1)}</text>
    </Frame>
  );
}

/* ---------- Figure 9: top-10 overlap ---------- */
function Overlap() {
  const rows = figs.overlap;
  const n = rows.reduce((s, r) => s + r.queries, 0);
  const mean = rows.reduce((s, r) => s + r.shared * r.queries, 0) / n;
  const low = rows.filter((r) => r.shared <= 2).reduce((s, r) => s + r.queries, 0);
  const x0 = 40, x1 = 700, yb = 220, y0 = 20;
  const bw = (x1 - x0) / rows.length;
  const X = (s: number) => x0 + s * bw;
  const Y = (v: number) => yb - (v / 70) * (yb - y0);
  return (
    <Frame
      title={`For ${Math.round((low / n) * 100)}% of test queries, BM25 and MedCPT share at most 2 of their top 10 documents`}
      subtitle={`Number of test queries by documents shared between the two top-10 lists, n = ${n}`}
      source="results/runs/bm25.json and medcpt.json"
      height={270}
      label="Histogram of shared top-10 documents between BM25 and MedCPT"
    >
      <line x1={x0} x2={x1} y1={yb} y2={yb} stroke={C.muted} />
      {rows.map((r) => (
        <g key={r.shared}>
          <rect x={X(r.shared) + 6} y={Y(r.queries)} width={bw - 12} height={yb - Y(r.queries)} fill={r.shared <= 2 ? C.accent : C.muted} fillOpacity={r.shared <= 2 ? 0.85 : 0.6}>
            <title>{`${r.shared} shared: ${r.queries} queries`}</title>
          </rect>
          <text x={X(r.shared) + bw / 2} y={Y(r.queries) - 6} textAnchor="middle" fill={C.ink}>{r.queries}</text>
          <text x={X(r.shared) + bw / 2} y={yb + 18} textAnchor="middle" fill={C.quiet}>{r.shared}</text>
        </g>
      ))}
      <text x={(x0 + x1) / 2} y={yb + 40} textAnchor="middle" fontSize={11.5} fill={C.quiet}>documents in both top-10 lists</text>
      <line x1={X(mean) + bw / 2} x2={X(mean) + bw / 2} y1={y0} y2={yb} stroke={C.ink} strokeDasharray="4 4" />
      <text x={X(mean) + bw / 2 + 6} y={y0 + 12} fontSize={11.5} fill={C.quiet}>mean {fmt(mean, 1)}</text>
    </Frame>
  );
}

const FIGURES: Record<string, () => React.ReactElement> = {
  architecture: Architecture,
  saturation: Saturation,
  idf: Idf,
  rrf: RrfDecay,
  recall: Recall,
  forest: Forest,
  pool: Pool,
  cost: Cost,
  scores: Scores,
  overlap: Overlap,
};

export default function PaperFigure({ name }: { name: string }) {
  const Fig = FIGURES[name];
  if (!Fig) throw new Error(`Unknown paper figure: ${name}`);
  return <Fig />;
}
